import sys
from itertools import product

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    s = sys.stdin.readline().strip()

    if n == 1:
        print(a[0])
        return

    max_val = -float('inf')
    best_expr = None

    for symbols in product(s, repeat=n-1):
        expr = []
        for i in range(n):
            expr.append(str(a[i]))
            if i < n-1:
                expr.append(symbols[i])
        current_expr = ''.join(expr)
        try:
            current_val = eval(current_expr)
        except:
            continue
        if current_val > max_val:
            max_val = current_val
            best_expr = current_expr
        elif current_val == max_val:
            if best_expr is None or len(current_expr) < len(best_expr):
                best_expr = current_expr

    print(best_expr)

solve()

